import java.util.*;

public class Main {
    public static void main(String[] args) {
        TreeSet<Integer> ts = new TreeSet<>(
            Arrays.asList(15, 5, 25, 10, 35, 20, 30)
        );
        System.out.println("TreeSet:        " + ts);
        System.out.println("first():        " + ts.first());
        System.out.println("last():         " + ts.last());
        System.out.println("ceiling(18):    " + ts.ceiling(18));
        System.out.println("floor(18):      " + ts.floor(18));
        System.out.println("headSet(20):    " + ts.headSet(20));
        System.out.println("tailSet(20):    " + ts.tailSet(20));
        System.out.println("subSet(10,25):  " + ts.subSet(10, 25));
        System.out.println("descendingSet:  " + ts.descendingSet());
    }
}

